def flood_gap(g, mingap=2):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; q=DQ()
    # seed border cells; movement blocked by walls or gaps < mingap at border
    for i,j in [(i,j) for i in range(H) for j in range(W) if g[i][j]==0 and (i in(0,H-1) or j in(0,W-1))]:
